package db

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"
)

// dbDir is the absolute path to the repository's db/ directory, resolved from
// this source file's own location so it does not depend on the process working
// directory. Same technique, and same reason, as static.DevAssetsDir.
var dbDir = func() string {
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		return "db"
	}
	return filepath.Join(filepath.Dir(thisFile), "..", "..", "db")
}()

// StructureSQL returns db/structure.sql, the schema snapshot generated by
// `make db-migrate` from the migrations in db/migrations.
//
// It is read from disk rather than //go:embed'd on purpose: nothing in
// production uses it. Only tests and the dev-only `db-init` command do, and
// embedding it shipped a schema snapshot inside every release binary.
func StructureSQL() (string, error) {
	contents, err := os.ReadFile(filepath.Join(dbDir, "structure.sql"))
	if err != nil {
		return "", fmt.Errorf("read schema snapshot: %w", err)
	}
	return string(contents), nil
}
